# Generated by Phase: IMPLEMENT | Feature: EVOL-106
"""Every external client in a time-limited function is bounded (EVOL-106): `gate.py bounds`.

A function dies at its platform timeout; an external client with no bound holds the call until it does. The packs
under `security/bounds/<lang>.yml` (Semgrep, stack-conditional; a stack outside the shipped packs gets its pack built
at materialisation, held by `semgrep --test`) find each client construction and say one of two things:

  unbounded   no whole-call deadline, and a connect bound, a per-attempt read bound or an attempt count is missing
              (a client with no built-in retry counts 1 attempt by construction; a bound that does not bind is absent).
  extract     its literal bounds, through the rule message (Semgrep's JSON carries no metavariables logged out):
              `bound <total|retries> <connect> <unit> <read> <unit> <attempts>` or `deadline <value> <unit>`.

This module does the arithmetic Semgrep does not: units to seconds (`s`, `ms`, `m` and the words the SDKs write —
`ofSeconds`, `FromMilliseconds`, `from_secs`, `Second` …), a retries-only count plus the first try. Red when:
  - an unbounded finding is not in the shrink-only baseline `docs/project_log/bounds_baseline.json`
    (`unbounded: {"path#rule": count}`; `--baseline --init` once, `--refresh` only shrinks);
  - a literal bound in code matches no client a function declares in `docs/spec/*/design.md` — the bound was chosen
    without the arithmetic;
  - a function resource (`infrastructure_needs.resources[]`, `type: function`) carries no `clients:` list, or the sum
    over its clients of calls × (deadline_s, or attempts × (connect_s + read_s)) exceeds its `timeout_seconds`;
  - an extract rule emits a message outside the grammar (the pack is broken, never a pass).

n/a in the framework repo and unless `hosting.type == function`. A full-loop member, like sast (it needs semgrep): never in the light profile.
"""
from __future__ import annotations

import json
import re
import shutil
import subprocess
from pathlib import Path

from . import documents
from .common import GateFault, clean, context, glob_match, parse_yaml, tracked_files

PACKS = "security/bounds"
BASELINE = "docs/project_log/bounds_baseline.json"
DESIGN_GLOB = "docs/spec/*/design.md"
BOUND = re.compile(r"^bound (total|retries) (\S+) (\S+) (\S+) (\S+) (\S+)$")
DEADLINE = re.compile(r"^deadline (\S+) (\S+)$")
SECONDS = {"s": 1.0, "sec": 1.0, "secs": 1.0, "second": 1.0, "seconds": 1.0,
           "ms": 0.001, "milli": 0.001, "millis": 0.001, "millisecond": 0.001, "milliseconds": 0.001,
           "m": 60.0, "min": 60.0, "mins": 60.0, "minute": 60.0, "minutes": 60.0}
YAML_BLOCK = re.compile(r"(?ms)^```ya?ml[ \t]*\n(.*?)^```")
SEMGREP_TIMEOUT = 900
EPS = 1e-9


def applies(repo: Path) -> str | None:
    """None when the check applies; else the reason it is n/a."""
    if context(repo) == "meta":
        return "the framework repo ships the packs; it runs no function"
    from . import data
    t = data.answers(repo).get("hosting.type")
    if t != "function":
        return f"hosting.type is {t!r}, not function — no platform timeout to bound against"
    return None


def seconds(value: str, unit: str) -> float:
    """A literal and the unit the code wrote → seconds. GateFault on anything else (the pack emitted it)."""
    u = unit.strip().lower()
    for p in ("from_", "from", "of"):
        if u.startswith(p) and u[len(p):] in SECONDS:
            u = u[len(p):]
            break
    if u not in SECONDS:
        raise GateFault(f"unit `{unit}` is none of s, ms, m (or the SDK words for them)")
    v = value.replace("_", "").rstrip("lL")
    try:
        n = float(v)
    except ValueError:
        raise GateFault(f"`{value}` is not a number") from None
    return n * SECONDS[u]


def normalise(message: str) -> dict:
    """An extract message → {deadline_s} or {connect_s, read_s, attempts}; GateFault outside the grammar."""
    msg = " ".join(message.split())
    m = DEADLINE.fullmatch(msg)
    if m:
        return {"deadline_s": seconds(m.group(1), m.group(2))}
    m = BOUND.fullmatch(msg)
    if not m:
        raise GateFault("not `bound <total|retries> <connect> <unit> <read> <unit> <attempts>` nor `deadline <value> <unit>`")
    n = m.group(6).replace("_", "")
    if not n.isdigit():
        raise GateFault(f"attempts `{m.group(6)}` is not a whole number")
    return {"connect_s": seconds(m.group(2), m.group(3)), "read_s": seconds(m.group(4), m.group(5)),
            "attempts": int(n) + (1 if m.group(1) == "retries" else 0)}


def scan(repo: Path, runner=subprocess.run) -> list[dict]:
    """The packs over the tree → [{rule, path, line, kind, client, message}]. GateFault when semgrep cannot judge."""
    if runner is subprocess.run and not shutil.which("semgrep"):
        raise GateFault("semgrep is absent — the bounds member runs the packs under security/bounds with it (the sast member's engine)")
    cmd = ["semgrep", "scan", "--config", PACKS, "--json", "--metrics=off", "--disable-version-check", "--quiet", "."]
    try:
        r = runner(cmd, cwd=str(repo), capture_output=True, text=True, timeout=SEMGREP_TIMEOUT)
    except (OSError, subprocess.TimeoutExpired) as e:
        raise GateFault(f"semgrep could not run ({e.__class__.__name__}) — the bounds member cannot judge") from None
    try:
        doc = json.loads(r.stdout or "")
    except ValueError:
        raise GateFault(f"semgrep exited {r.returncode} with no JSON — {clean((r.stderr or '').strip()[-300:])}") from None
    if r.returncode not in (0, 1):   # a file semgrep cannot parse is skipped, never a stop (probed on 1.182.0)
        errs = "; ".join(clean(str(e.get("message") or e.get("type")), 120) for e in (doc.get("errors") or [])[:3])
        raise GateFault(f"semgrep exited {r.returncode} — {errs or 'no results'}; the packs are not runnable")
    out = []
    for x in doc.get("results") or []:
        ex = x.get("extra") or {}
        md = ex.get("metadata") or {}
        rule = str(x.get("check_id") or "").rsplit(".", 1)[-1]
        msg = str(ex.get("message") or "")
        kind = md.get("bounds") or ("extract" if re.match(r"^(bound|deadline) ", msg) else "unbounded")
        if kind not in ("unbounded", "extract"):   # a pack typo is a broken pack, never a dropped finding
            raise GateFault(f"rule {rule} declares metadata.bounds {kind!r} — only `unbounded` or `extract`; the pack is broken")
        out.append({"rule": rule, "path": str(x.get("path") or ""), "line": (x.get("start") or {}).get("line"),
                    "kind": kind, "client": md.get("client") or rule, "message": msg})
    return out


def functions(repo: Path, outage: "documents.Outage | None" = None) -> tuple[list[dict], list[str]]:
    """The function resources every design declares → ([{at, id, timeout, clients}], problems). With `outage`, a store
    down leaves that design unjudged and is settled by the caller (EVOL-080 § 3)."""
    fns, probs = [], []
    for rel in sorted(p for p in documents.artefacts(tracked_files(repo)) if glob_match(p, DESIGN_GLOB)):
        disk = repo / rel   # a file wins over its pin; a pinned design is read at its pinned version (EVOL-080)
        try:
            text = disk.read_text(encoding="utf-8", errors="replace") if disk.is_file() else documents.text(repo, rel)
        except documents.StoreDown as e:
            if outage is None:
                raise
            outage.note(e); continue
        except GateFault as e:   # a pin the store does not honour is red, never infra
            probs.append(f"{rel}: {e}"); continue
        if text is None:
            continue
        for block in YAML_BLOCK.findall(text):
            if "infrastructure_needs" not in block:
                continue
            try:
                doc = parse_yaml(block)
            except GateFault as e:
                probs.append(f"{rel}: the infrastructure_needs block is not readable YAML ({e})"); continue
            res = ((doc or {}).get("infrastructure_needs") or {}).get("resources") if isinstance(doc, dict) else None
            for r in res if isinstance(res, list) else []:
                if isinstance(r, dict) and r.get("type") == "function":
                    fns.append({"at": rel, "id": str(r.get("id") or "(no id)"), "timeout": r.get("timeout_seconds"), "clients": r.get("clients")})
    return fns, probs


def _num(v) -> float | None:
    return float(v) if isinstance(v, (int, float)) and not isinstance(v, bool) and v >= 0 else None


def budget(fn: dict) -> tuple[float, list[str], list[dict]]:
    """A function's worst case over its declared clients → (seconds, problems, normalised clients)."""
    where = f"{fn['at']} function `{fn['id']}`"
    t = _num(fn["timeout"])
    probs = [] if t else [f"{where}: no numeric `timeout_seconds` — the platform timeout every client bound is measured against"]
    cl = fn["clients"]
    if not isinstance(cl, list):
        return 0.0, probs + [f"{where}: no `clients:` list — declare each external client with its bounds, or `clients: []` when it calls none"], []
    total, norm = 0.0, []
    for c in cl:
        name = str((c or {}).get("name") or "(no name)") if isinstance(c, dict) else "(not a mapping)"
        calls = c.get("calls") if isinstance(c, dict) else None
        if not isinstance(calls, int) or isinstance(calls, bool) or calls < 1:
            probs.append(f"{where}: client `{name}` has no whole `calls` ≥ 1"); continue
        d = _num(c.get("deadline_s"))
        if d is not None:
            norm.append({"deadline_s": d}); total += calls * d; continue
        k, rd, a = _num(c.get("connect_s")), _num(c.get("read_s")), c.get("attempts")
        if k is None or rd is None or not isinstance(a, int) or isinstance(a, bool) or a < 1:
            probs.append(f"{where}: client `{name}` carries neither `deadline_s` nor `connect_s`, `read_s` and whole `attempts` ≥ 1"); continue
        norm.append({"connect_s": k, "read_s": rd, "attempts": a}); total += calls * a * (k + rd)
    if t and total > t + EPS:
        probs.append(f"{where}: its clients can take {total:g} s (Σ calls × attempts × (connect + read), or × deadline) — over timeout_seconds {t:g}; lower a bound or raise the timeout")
    return total, probs, norm


def _same(a: dict, b: dict) -> bool:
    return a.keys() == b.keys() and all(abs(float(a[k]) - float(b[k])) <= EPS for k in a)


def read_baseline(repo: Path) -> dict:
    p = repo / BASELINE
    if not p.is_file():
        return {}
    try:
        doc = json.loads(p.read_text(encoding="utf-8"))
    except (OSError, ValueError) as e:
        raise GateFault(f"the baseline {BASELINE} is unreadable ({e.__class__.__name__}) — fix it or delete it and --baseline --init again") from None
    u = doc.get("unbounded") if isinstance(doc, dict) else None
    if not isinstance(u, dict) or not all(isinstance(v, int) and v > 0 for v in u.values()):
        raise GateFault(f"the baseline {BASELINE} must carry `unbounded`: {{\"path#rule\": count}}")
    return u


def _counts(found: list[dict]) -> dict:
    out: dict = {}
    for f in found:
        if f["kind"] == "unbounded":
            k = f"{f['path']}#{f['rule']}"
            out[k] = out.get(k, 0) + 1
    return out


def check(repo: Path, runner=subprocess.run) -> dict:
    why = applies(repo)
    if why:
        return {"ok": True, "na": True, "entries": [], "reason": why}
    if not (repo / PACKS).is_dir() or not any((repo / PACKS).glob("*.yml")):
        return {"ok": False, "entries": [], "reason": f"no pack under {PACKS}/ — the materialisation lands the stack's pack or builds one (SETUP --upgrade)"}
    found = scan(repo, runner)
    base, cur = read_baseline(repo), _counts(found)
    grown = [f"{k}: {n} unbounded client(s), the baseline holds {base.get(k, 0)} — bound it (connect, read, attempts, or a deadline)"
             for k, n in sorted(cur.items()) if n > base.get(k, 0)]
    stale = [f"{k}: the baseline holds {n}, the code {cur.get(k, 0)} — it only shrinks: gate.py bounds --baseline --refresh"
             for k, n in sorted(base.items()) if cur.get(k, 0) < n]
    outage = documents.Outage()
    fns, fprobs = functions(repo, outage)
    declared, fn_probs = [], list(fprobs)
    for fn in fns:
        _, p, norm = budget(fn)
        fn_probs += p
        declared += norm
    lit = []
    for f in (x for x in found if x["kind"] == "extract"):
        where = f"{f['path']}:{f['line']}"
        try:
            b = normalise(f["message"])
        except GateFault as e:
            lit.append(f"{where}: rule {f['rule']} emitted «{clean(f['message'], 80)}» — {e} (the pack is broken)"); continue
        if not any(_same(b, d) for d in declared):
            shown = ", ".join(f"{k} {v:g}" for k, v in b.items())
            lit.append(f"{where}: {f['client']} is bounded at {shown}, which no function declares under `clients:` — the bound was chosen without the arithmetic")
    rows = [{"id": "unbounded", "ok": not (grown or stale), "problems": grown + stale,
             "note": f"{sum(cur.values())} unbounded client(s), every one in the baseline" if cur else "no unbounded client"},
            {"id": "declared", "ok": not lit, "problems": lit, "note": "every literal bound is a client a function declares"},
            {"id": "functions", "ok": not fn_probs, "problems": fn_probs,
             "note": f"{len(fns)} function(s): their clients fit timeout_seconds"}]
    red = [r for r in rows if not r["ok"]]
    outage.settle(red)
    return {"ok": not red, "entries": rows, "reason": f"{len(red)} of {len(rows)} red" if red else "every external client is bounded within its function's timeout"}


def baseline(repo: Path, init: bool = False, refresh: bool = False, runner=subprocess.run) -> dict:
    why = applies(repo)
    if why:
        raise GateFault(f"the bounds check does not apply here ({why}) — no baseline to write")
    p = repo / BASELINE
    cur = _counts(scan(repo, runner))
    if init:
        if p.is_file():
            raise GateFault(f"the baseline {BASELINE} exists — it only shrinks (--refresh); delete it by decision if it must be re-taken")
        items = cur
    elif refresh:
        old = read_baseline(repo)
        items = {k: min(n, cur[k]) for k, n in old.items() if cur.get(k)}
    else:
        raise GateFault("--baseline needs --init (record the debt once) or --refresh (shrink it)")
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps({"_doc": "Client-bounds baseline (EVOL-106): unbounded clients at adoption. New clients are bounded; this map only shrinks (python3 scripts/gate.py bounds --baseline --refresh). Commit this file.",
                             "unbounded": dict(sorted(items.items()))}, indent=2) + "\n", encoding="utf-8")
    return {"ok": True, "path": BASELINE, "unbounded": items}


def render(res: dict, name: str = "bounds") -> str:
    from .delivery import render as _render
    return _render(res, name)
